\label{lem:quasiline_from_qc}
Let $\sigma\colon G\to \mathbb{Z}/2\mathbb{Z}$ be a homomorphism with kernel $K$, and let $\phi\colon G\to \mathbb{R}$ be an
unbounded $\sigma$-quasicocycle, which restricts to a homogeneous quasimorphism on $K$. Let $C\ge 0$ be
such that $D(\phi)\le C/2$ and $\phi(K)\cap (0,C/2)\neq \emptyset$; if $K\lneq G$ suppose also that $\phi(G-K)\cap [0,C/2)\neq \emptyset$. Let $X \coloneq \{g \in G \mid|\phi(g)| < C\}$. Then $X$ generates $G$, and the map $\phi\colon \operatorname{Cay}\left(G,X\right)\to \mathbb{R} $ is a quasi-isometry. Furthermore:
\begin{enumerate}
            \item \label{item:qc1} $g\in G$ acts loxodromically on $\operatorname{Cay}\left(G,X\right)$ if and only if $\phi$ is unbounded on $\langle g\rangle$.
            \item \label{item:qc2} $g\in G$ fixes the ideal endpoints of $\operatorname{Cay}\left(G,X\right)$ if and only if $g\in K=\ker(\sigma)$.
            \item \label{item:qc3} If $H\le K$ is such that $|\phi|_{H}|$ is bounded, then $H$ acts on $\operatorname{Cay}\left(G,X\right)$ with uniformly bounded orbits.
        \end{enumerate}

Let $G$ be a group, and let $X$ be a generating set such that $\Gamma\coloneq \operatorname{Cay}\left(G,X\right)$ is hyperbolic. A subgroup $H\le G$ is \emph{hyperbolically embedded} in $(G,X)$, denoted $H\hookrightarrow_h (G,X)$, if
    \begin{itemize}
        \item $H$ is finitely generated by a subset $Y$;
        \item $H$ is quasi-isometrically embedded: there exist constants $L,c$ such that, for all $h\in H$, $|h|_Y\le L|h|_{X}+c$;
        \item $H$ is \emph{geometrically separated}: for every $\varepsilon> 0$ there exists $R\ge 0 $ such that, for every $g\in G$, if $\mathrm{diam}_\Gamma(H\cap N_\varepsilon(gH))\ge R$, then $i=j$ and $g\in H$.
    \end{itemize}

Let $t\in G$ be a loxodromic element for the action on $\operatorname{Cay}\left(G,X\right)$ such that $E(t)$ surjects onto $\mathbb{Z}$, which exists by e.g. \cite[Lemma 6.16]{DGO}. The surjection $q\colon E(t)\to \mathbb{Z}$, seen as a homogeneous quasimorphism $E(t)\to \mathbb{R}$, can be extended to a homogeneous quasimorphism $Q\colon G\to \mathbb{R}$ by a result of Hull and Osin \cite[Theorem 1.4]{Hull_Osin}, later generalised by Frigerio, Pozzetti, and Sisto \cite[Theorem 1]{FPS} to higher dimensional quasicocycles. Our goal is to go through the latter construction to show that $Q$ is actually coarsely Lipschitz with respect to $X$. 

    We recall some notation from \cite{FPS}, see also \cite[Chapter 9]{BCSV} for a gentle walk-through.
    Endow $\operatorname{Cay}\left(G,X\right)$ with the usual path metric where edges have length one, and let $(\hat G,\hat \mathrm{d})$ be the metric graph obtained from $\operatorname{Cay}\left(G,X\right)$ by adding a vertex $c(B)$ for every coset $B$ and connecting every $x\in B$ to $c(B)$ via an edge of length $1/4$. Let $\mathrm{d}_{E({t})}\colon E(t)\times E(t)\to [0,+\infty]$ be the \emph{relative metric} from \cite[Definition 4.25]{DGO}; for our purposes, it will suffice to know that $\mathrm{d}_{E(t)}$ is $E(t)$-left-invariant and bounded from above by $\mathrm{d}_{\operatorname{Cay}\left(G,X\right)}$. For every $g\in G$ one then sets $\mathrm{d}_{gE(t)}$ as the $g$-translate of $\mathrm{d}_{E(t)}$; this is well-defined by left-invariance of $\mathrm{d}_{E(t)}$. Define $\pi_B\colon G\to B$ by sending $x\in G$ to the set of all $y\in B$ realising the distance $\hat\mathrm{d}(x,B)$. 
    \begin{claim}
        There exists $D\ge 1$ such that, if $g,h\in G$ satisfy $\mathrm{d}_{\operatorname{Cay}\left(G,X\right)}(g,h)\le 1$, then the diameter of $\pi_B(g)\cup \pi_B(h)$, with respect to $\mathrm{d}_B$, is at most $D$. 
    \end{claim}
    \begin{claimproof} \cite[Lemma 2.8]{FPS} grants the existence of a constant $D\ge 1$ such that, if the diameter of $\pi_B(g)\cup \pi_B(h)$ is at least $D$, then every $\hat G$-geodesic between $g$ and $h$ passes through $c(B)$. If $g=h$ we are done by the Lemma; hence suppose $g$ and $h$ are $X$-adjacent, and therefore $\hat\mathrm{d}(g,h)\le 1$. By the Lemma, if the diameter of their projections was greater than $D$, then the $X$-edge between them would not be a geodesic, so $\hat\mathrm{d}(g,h)$ would have to be $1/2$; as a consequence, the unique geodesic between $g$ and $h$ would have to be the path $\{g,c(B),h\}$, meaning that $g,h$ would belong to $B$. However this is impossible, as then $g=\pi_B(g)$, $h=\pi_B(h)$, and $\mathrm{d}_B(g,h)\le \mathrm{d}_{\operatorname{Cay}\left(G,X\right)}(g,h)=1$ as they are $X$-adjacent. 
    \end{claimproof}
    \noindent Now, the homogeneous quasimorphism $Q\colon G\to \mathbb{R}$ extending $q$ is the homogeneisation of the quasimorphism $Q_0$ sending each $g\in G$ to
    \[Q_0(g)\coloneq \sum\frac{1}{|\pi_B(1)\cup \pi_B(g)|}\sum_{x\in \pi_B(1),\,y\in\pi_B(g)}q(x^{-1}y), \]
    where the sum is over all $B\in G/E(t)$ such that $\mathrm{diam}_B(\pi_B(1)\cup \pi_B(g))>2D$. Notice that $Q_0$ is trivial on $X$ by the Claim; in turn, by \Cref{defn:homogeneisation}, we get $\sup_{x\in X}|Q(x)|\le \delta$, where $\delta$ is the defect of $Q_0$. Hence, for every $g,h\in G$, we have
    \begin{align*}
        |Q(g)-Q(h)|=|Q(g)+Q(h^{-1})|&\le 2\delta+ |Q(gh^{-1})|\\
        &\le 2\delta+|gh^{-1}|_X\left(2\delta+\sup_{x\in X}|Q(x)|\right)\\&\le 2\delta+3\delta|gh^{-1}|_X,
    \end{align*}
    where we repeatedly used that the the defect of $Q$ is $2\delta$ by \Cref{defn:homogeneisation}. If we set $L=3\delta$, the above inequality concludes the proof.

\label{defn:HHG}
Let $G$ be a finitely generated group. We say $G$ is a \textit{hierarchically hyperbolic group} (HHG) if the following hold.
    \begin{enumerate}[label=(\roman*{})]
        \item\label{HHG_structure} There exists a HHS $(Z,\mathfrak S)$ such that $G$ acts metrically properly and coboundedly on $Z$. 
        \item\label{HHG_action} There is a $\sqsubseteq$--, $\perp$--, and $\pitchfork$--preserving action of $G$ on $\mathfrak S$ by bijections such that $\mathfrak S$ contains finitely many $G$--orbits.
        \item\label{HHG_isometries} For each $W\in \mathfrak S$ and $g\in G$, there exists an isometry $g_W\colon \mathcal C W \to \mathcal C (gW)$ satisfying the following for all $V,W\in\mathfrak S$, $h\in G$, and $x\in Z$.
            \begin{itemize}
                \item The maps $(gh)_W\colon \mathcal C W \to \mathcal C (ghW)$ and $g_{hW}\circ h_W\colon \mathcal C W\to \mathcal C (ghW)$ coincide.
                \item $g_W(\pi_W(x))=\pi_{gW}(g\cdot x)$.
                \item If $V\pitchfork W$ or $V\sqsubsetneq W$, then $g_W(\rho^V_W)=\rho^{gV}_{gW}$.
            \end{itemize}
    \end{enumerate}
In \Cref{HHG_isometries} we often drop the subscript on the isometry $g_W$ and simply write $g$ when the domain $W$ is clear from context.

By combining \cite[Lemma 5.5 and Construction 5.10]{HHS_II}\footnote{A note for experts: for the simplified definitions of $P_U$ and $\mathfrak{g}_U$ we give here to be equivalent to the ones from \cite{HHS_I}, one should first assume $E$ is sufficiently large that the tuple $\{\pi_W(x)\}_{W\sqsubseteq U\mbox{ or }W\bot U}\cup \{\rho^U_W\}_{W\pitchfork U\mbox{ or } U\sqsubsetneq W}$ is $E$-consistent for all $x\in Z$, and can be $E$-coarsely realised. Since we will always deal with HHGs, which have finitely many $G$-orbits of domains, we can once and for all replace $E$ by a large enough constant, and forget about these technicalities.} there exists a coarsely Lipschitz map $\mathfrak{g}_U\colon Z\to P_U$, which maps a point $x\in Z$ to the coarsely unique point $\mathfrak{g}_U(x)\in P_U$ such that:
\begin{itemize}
    \item For all $W\sqsubseteq U$ or $W\bot U$, $\mathrm{d}_{W}(x,\mathfrak{g}_U(x))\le E$;
    \item For all $U\sqsubsetneq W$ or $W\pitchfork U$, $\mathrm{d}_{W}(\rho^U_W,\mathfrak{g}_U(x))\le E$.
\end{itemize}

\label{defn:coarse_median}
A \emph{coarse median space} is a metric space $(Z,\mathrm{d})$ equipped with a symmetric ternary operation $\mu\colon Z^3\to Z$, called a \emph{coarse median}, satisfying the following, for some constant $R\ge 0$:
\begin{itemize}
  \item \emph{Localisation}: $\mu(x,x,y)=a$ for all $x,y\in  Z $;
 \item \emph{Coarsely Lipschitz}: for all $x,x',y,z\in  Z $, we have
      $$d(\mu(x,y,z), \mu(x',y,z)) \leqslant Rd(x,x')+R;$$
  \item \emph{Coarse associativity}: for all $x,y,z,p\in  Z $, we have
\[
\mathrm{d}\left(\mu\left(\mu(x,p,y),p,z\right), \mu\left(x,p,\mu(y,p,z)\right)\right)\le R.
\]
 \end{itemize}
 Two coarse median $\mu_1,\mu_2\colon  Z ^3\to  Z $ are \emph{equivalent}, and we write $\mu_1\sim \mu_2$, if \[\sup_{x,y,z\in  Z } \mathrm{d}_{ Z }(\mu_1(x,y,z),\mu_2(x,y,z))<+\infty;\] an equivalence class of coarse medians is called a \emph{coarse median structure}. 

 Let $G$ be a finitely generated group, and let $Z$ be a Cayley graph for $G$ with respect to a finite generating set. A coarse median structure on $Z$ is \emph{$G$-equivariant} if, given any representative $\mu$ in the equivalence class, $\mu \sim g\mu(g^{-1}(\cdot),g^{-1}(\cdot),g^{-1}(\cdot)) $; a group equipped with an equivariant coarse median structure is called a \emph{coarse median group}.

\label{notation:tweakable_hhg}
    Let $G$ be a HHG, with underlying HHS $(Z,\mathfrak S)$. We assume the following facts hold:
    \begin{enumerate}
        \item \label{need:prodregions} $(Z,\mathfrak S)$ has clean containers (\Cref{defn:CC}) and cobounded product regions (\Cref{defn:cobounded_pr}).
        \item \label{need:annular_curve_graph} There exists a minimal domain $\ell\in \mathfrak S$ whose coordinate space $\mathcal C \ell$ is a quasiline.
        \item \label{need:orth_compl} The orthogonal complement $\ell^\bot$ is unbounded, it is nested in no unbounded domain possibly except $S$, and $(\ell^\bot)^\bot=\ell$. Furthermore, for any $W\in \mathfrak S$, if $\ell\pitchfork W$ then $\ell^\bot\pitchfork W$. 
        \item \label{need:dehntwist} There exists $T\in \operatorname{Stab}_{G}(\ell)$ such that $\langle T\rangle$ is normal in $\operatorname{Stab}_{G}(\ell)$, it acts loxodromically on $\mathcal C\ell$ and trivially on $\mathfrak S_\ell^\bot$, and for every $W\in \mathfrak S_\ell^\bot$ the orbits of $\langle T\rangle$ in $\mathcal C W$ are uniformly bounded. 
        \item \label{need:acylindricity} $H\coloneq \operatorname{Stab}_{G}(\ell)/\langle T\rangle $ is not virtually cyclic, and the induced $H$-action on $\mathcal C \ell^\bot/\langle T\rangle$ is acylindrical.
    \end{enumerate}

\label{prop:new_hhg_structures}
     In the setting of \Cref{notation:tweakable_hhg} and \Cref{construction:newline}, for any $\lambda\in \mathbb{R}$ there exists a HHG structure for $(G,\mathfrak S_\lambda)$ such that:
     \begin{itemize}
         \item The underlying metric space is $Z$, and the domain set is $\mathfrak S_\lambda=\mathfrak S$, with the same relations;
         \item For every $W\not\in G\cdot \ell$, $\mathcal C W$ is unchanged;
         \item For every $g\in G$, $\mathcal C{(g\ell)}=g L_\lambda$.
     \end{itemize}
     Furthermore, $\langle T\rangle$ acts loxodromically on $L_\lambda$ and with uniformly bounded orbits on $\mathcal C W$ whenever $W\in \mathfrak S_\lambda$ is orthogonal to $\ell$.

We shall prove one axiom from \Cref{defn:HHS} and \Cref{defn:HHG} at a time, introducing all relevant data as soon as we shall need them. Each axiom will be proven with some choice of the HHS constant, and we shall eventually set the HHS constant for $(G,\mathfrak S_\lambda)$ as the maximum of these values. To avoid confusion, when we want to distinguish between the original and the new projections, we denote the copy of $\ell$ for the structure depending on $\lambda$ by $\ell_\lambda$: for instance, $\pi_{\ell_\lambda}$ will denote the new projection to $L_\lambda$, while $\pi_\ell$ will denote the original projection to $\mathcal C \ell$. For two subsets $A,B$ of a metric space, we will use the notation $A\sim B$ to mean that the Hausdorff distance between $A$ and $B$ is bounded by a uniform constant, possibly depending on the original structure $(Z,\mathfrak S)$ and on $\lambda$.

\medskip\textbf{(Projections.)} If $W\not\in G\cdot \ell$, let $\pi_W\colon Z\to \mathcal C W$ be the original projection. Next, fix an identification of $\operatorname{Stab}_{G}(\ell)$ with $P_\ell$ given by cobounded product regions, so that for all $g\in G$ the coset $g\operatorname{Stab}_{G}(\ell)$ is identified with the subspace $gP_\ell=P_{g\ell}$; then set $\pi_{g\ell_\lambda}\colon Z\to gL_\lambda$ as the composition of the gate map $\mathfrak{g}_{g\ell}\colon Z\to g\operatorname{Stab}_{G}(\ell)$ and the identity map $g\operatorname{Stab}_{G}(L)\to gL_\lambda=g\operatorname{Cay}\left(\operatorname{Stab}_{G}(\ell),S_\lambda\right)$. We stress that $\mathfrak{g}_{g\ell}$ is defined using the original HHG structure, and as such does not depend on $\lambda$. The projection $\pi_{\ell_\lambda}$ does not depend on the choice of the coset representative $g$, since both $\mathfrak{g}_\ell$ and the projection to $L_\lambda$ are $\operatorname{Stab}_{G}(\ell)$-equivariant; furthermore, it is a coarsely Lipschitz coarse map as so are its factors. Finally, by construction $g\pi_{\ell_\lambda}(x)=\pi_{g\ell_\lambda}(gx)$ for all $x\in Z$ and $g\in G$, so the new projections are uniformly coarsely Lipschitz coarse maps. 
        \\
        For later purposes, we point out that $\pi_{\ell_\lambda}$ only depends on the original projections on $\mathcal C \ell$ and $\mathcal C \ell^\bot$:
        \begin{claim}\label{claim:what_determines_pilambda}
            For every $A\subseteq G$, $\mathrm{diam} \pi_{\ell_\lambda}(A)$ is bounded in terms of $\max\{\mathrm{diam} \pi_{\ell}(A), \mathrm{diam} \pi_{\ell^\bot}(A)\}$.
        \end{claim}
        \begin{claimproof}[Proof of \Cref{claim:what_determines_pilambda}] There is nothing to prove if either $\pi_{\ell}(A)$ or $\pi_{\ell^\bot}(A)$ are unbounded, so suppose otherwise. Taking the gate to $P_{\ell}$ does not change the coordinates in $\mathcal C \ell$ and $\mathcal C \ell^\bot$, so $B\coloneq \mathfrak{g}_\ell(A)$ has bounded projections to $\mathcal C \ell$ and $\mathcal C \ell^\bot$. Now, by construction $\pi_{\ell_\lambda}(A)$ is the projection of $B$ to $L_\lambda$; since $\theta_\lambda=\phi+\lambda\psi\colon L_\lambda\to \mathbb{R}$ is a quasi-isometry, it is enough to show that both $\phi$ and $\psi$ are bounded on $B$, when we identify the latter with a subset of $\operatorname{Stab}_{G}(\ell)$.  Now we analyse one quasicocycle at a time:
            \begin{itemize}
                \item Recall that $\phi$ is the Busemann quasicocycle associated to the action on $\mathcal C\ell$, as in \Cref{ex:busemann}, which depends on the choice of $i\in \operatorname{Stab}_{G}(\ell)$ and has the property that $\phi(ki)=\phi(k)$ for all $k\in K$. Now let $x\in  B$, and let $x'$ be either $x$ if $x\in K$, or $xi^{-1}$ if $x\not\in K$, so that $\phi(x')=\phi(x)$ while  $\pi_{\ell}(x')\sim \pi_\ell(x)$ belongs to a bounded subset. If we fix $x_0\in B$, for every other $x$ the difference $x'(x_0')^{-1}$ preserves a bounded subset, and therefore acts with uniformly bounded orbits on $\mathcal C\ell$ as it preserves orientation. Hence $\phi (x'(x_0')^{-1})=0$ for all $x\in  B$, meaning that $\phi(B)\sim \phi(x_0')$ is bounded.
                \item Furthermore, $\mathcal C\ell^\bot =\operatorname{Cay}\left(\operatorname{Stab}_{G}(\ell),X\right)$ and $\psi$ is $X$-coarsely-Lipschitz, hence $\psi(B)$ is bounded as so is $\pi_{\ell^\bot}(B)$.\qedhere
            \end{itemize}
        \end{claimproof}



        \medskip\textbf{(Nesting, finite complexity, orthogonality and containers.)} The relations on $\mathfrak S$ are the same as before, so these axioms already hold. Moreover, since the only domains whose coordinate spaces have been changed are $\sqsubseteq$-minimal, whenever $U\sqsubsetneq V$ we can define $\rho^U_V$ as before. 

        \medskip\textbf{(Transversality.)} If $V\pitchfork W$ and none is in the $G$-orbit of $\ell$, set $\rho^V_W$ as before. If instead, without loss of generality, $V=\ell$, we set $\rho^W_{\ell_\lambda}=\pi_{\ell_\lambda}(P_W)$, where $P_W$ is the product region for $W$. To see that the latter is a uniformly bounded subset of $L_\lambda$, first notice that $W\pitchfork \ell$ implies $W\pitchfork \ell^\bot$ by \Cref{notation:tweakable_hhg}.\eqref{need:orth_compl}. Furthermore, $\pi_\ell(P_W)\sim \rho^W_\ell$ and $\pi_{\ell^\bot}(P_W)\sim \rho^W_{\ell^\bot}$, by definition of the product region, and therefore $\pi_{\ell_\lambda}(P_W)$ is uniformly bounded by \Cref{claim:what_determines_pilambda}. Notice also that the new relative projections are $G$-equivariant by construction.


        \medskip\textbf{(Consistency.)}
        Let $x\in Z$, and let $V,W$ be two transverse domains. If none is a translate of $\ell$ there is nothing to prove, so up to the $G$-action assume that $V=\ell$. Suppose first that $W\not\in G\cdot \ell$; we shall prove the consistency inequality holds with some constant which is at least $4E$. Indeed, if $\mathrm{d}_{W}(x,\rho^\ell_W)>4E$ then $\mathrm{d}_{W}(x,\rho^{\ell^\bot}_W)> E$, where we used \Cref{lem:DHS}, the fact that $W$ is also transverse to $\ell^\bot$ by \Cref{notation:tweakable_hhg}.\eqref{need:orth_compl}, and that $\mathrm{diam}\rho^\ell_W\le E$ by definition of the HHG structure. The original consistency inequalities in $(Z,\mathfrak S)$ then yield that $\max\{\mathrm{d}_{\ell}(x,\rho^W_\ell),\mathrm{d}_{\ell^\bot}(x,\rho^W_{\ell^\bot})\}\le E$, so $\mathrm{d}_{L_\lambda}(x, \rho^W_{\ell_\lambda})=\mathrm{d}_{L_\lambda}(x, P_W)$ is uniformly bounded by \Cref{claim:what_determines_pilambda}.

        Now suppose that $\ell\pitchfork g\ell$ for some $g\in G-\{1\}$. By repeatedly applying \Cref{notation:tweakable_hhg}.\eqref{need:orth_compl} we see that $\ell\pitchfork g\ell^\bot$, $\ell^\bot\pitchfork g\ell$, and $\ell^\bot\pitchfork g\ell^\bot$. Now, by \Cref{claim:what_determines_pilambda} we can assume that $\mathrm{d}_{g\ell_\lambda}(x,\rho^\ell_{g\ell_\lambda})=\mathrm{d}_{g\ell_\lambda}(x,P_\ell)$ is large enough that $\max\{\mathrm{d}_{g\ell}(x,\rho^\ell_{g\ell}),\mathrm{d}_{g\ell^\bot}(x,\rho^\ell_{g\ell^\bot})\}>4E$. Then the above argument, where $W$ is whichever between $g\ell$ and $g\ell^\bot$ realises the maximum, runs verbatim to show that $\mathrm{d}_{L_\lambda}(x, \rho^W_{\ell_\lambda})$ is uniformly bounded. If $W=g\ell$ we are done. If instead $W=g\ell^\bot$ then notice that $\rho^{g\ell}_{\ell}\sim \rho^{g\ell^\bot}_\ell$ in $\mathcal C \ell$ and $\rho^{g\ell}_{\ell^\bot}\sim \rho^{g\ell^\bot}_{\ell^\bot}$ in $\mathcal C \ell^\bot$ by \Cref{lem:DHS}; therefore \[\rho^{g\ell}_{\ell_\lambda}=\pi_{L_\lambda}(P_{g\ell})\sim \pi_{L_\lambda}(P_{g\ell^\bot})= \rho^{g\ell^\bot}_{\ell_\lambda},\] where we used \Cref{claim:what_determines_pilambda} and how product regions project to domains.

        Finally, let $U\sqsubsetneq V$ and assume both $U$ and $V$ have a well-defined relative projection to $W$. Again there is nothing to prove if $W\not\in G\cdot \ell$, so suppose $W=\ell$ up to the $G$-action. Since $\ell$ is $\sqsubseteq$-minimal, we must have $V\pitchfork  \ell$ and $U\pitchfork  \ell$, so $V\pitchfork  \ell^\bot$ and $U\pitchfork  \ell^\bot$ as well by \Cref{notation:tweakable_hhg}.\eqref{need:orth_compl}. By the original consistency inequalities, $\rho^U_\ell\sim \rho^V_\ell$ and $\rho^U_{\ell^\bot}\sim \rho^V_{\ell^\bot}$; thus
        \[\rho^U_{\ell_\lambda}=\pi_{L_\lambda}(P_U)\sim\pi_{L_\lambda}(P_V) =\rho^V_{\ell_\lambda},\]
        where we again used \Cref{claim:what_determines_pilambda} and how the product regions $P_U$ and $P_V$ project to $\mathcal C\ell$ and $\mathcal C\ell^\bot$.


        \medskip\textbf{(Bounded geodesic image.)} Let $x,y\in G$ and let $V\sqsubsetneq W$; since we only replaced minimal domains, we just have to consider the case $V=\ell$.                                                                                                                                                                                  
        Notice that $W\not\bot\ell^\bot$, since $(\ell^\bot)^\bot=\ell$ by \Cref{notation:tweakable_hhg}.\eqref{need:orth_compl}, and clearly $W\not\sqsubseteq \ell^\bot$ or it would be orthogonal to $\ell$. Then either $\ell^\bot$ is either transverse to, or properly contained inside, $W$.                                                                                                                                       
        Now let $\gamma\subseteq \mathcal C W$ be a geodesic between $\pi_W(x)$ and $\pi_W(y)$. If $\mathrm{d}_W(\gamma, \rho^\ell_W)>4E$, then $\mathrm{d}_W(\gamma, \rho^{\ell^\bot}_W)>E$ as well by \Cref{lem:DHS}. Now the original bounded geodesic image axiom tells us that $\mathrm{d}_\ell(x,y)\le E$; furthermore, by either the bounded geodesic image axiom (if $ \ell^\bot\sqsubsetneq W$) or the consistency inequalities (if $\ell^\bot\pitchfork W$), we also get that $\mathrm{d}_{\ell^\bot}(x,y)$ is uniformly bounded. Then $\mathrm{d}_{L_\lambda}(x,y)$ is uniformly bounded by \Cref{claim:what_determines_pilambda}.

        \medskip\textbf{(Partial realization.)} The proof of this axiom will rely on the following claim, which also establishes the ``furthermore" part of the Theorem:
        \begin{claim}\label{claim:action_of_T}
            $\langle T\rangle$ acts loxodromically on $L_\lambda$ and with uniformly bounded orbits on $\mathcal C W$ whenever $W\in \mathfrak S_\lambda$ is orthogonal to $\ell$.
        \end{claim}

        \begin{claimproof}
            Since $\theta_\lambda(T)=\phi(T)\neq 0$, $\langle T\rangle$ still acts loxodromically on $L_\lambda$. If $W\bot\ell$ is not in the $G$-orbit of $\ell$, then $\langle T\rangle$ already acted with uniformly bounded orbits on $\mathcal C W$ by \Cref{notation:tweakable_hhg}.\eqref{need:dehntwist}, so there is nothing to prove. If instead $\ell\bot g\ell$ for some $g\in G$, by symmetry it is enough to show that $gTg^{-1}$ acts with uniformly bounded orbits on $L_\lambda$. Recall that $gTg^{-1}$ fixes by $\ell$ \Cref{notation:tweakable_hhg}.\eqref{need:dehntwist}, so it belongs to $\operatorname{Stab}_{G}(\ell)$; moreover, again by assumption, $g\langle T\rangle g^{-1}$ acts with uniformly bounded orbits on the original $\mathcal C\ell$, so it must commute with $T$ which acts loxodromically. Thus $gTg^{-1}$ belongs to the kernel of the $\operatorname{Stab}_{G}(\ell)$-action on $L_\lambda$. By \Cref{lem:quasiline_from_qc}.\eqref{item:qc3}, we are therefore left to prove that $\theta_\lambda(gTg^{-1})=0$. This is because $\phi(gTg^{-1})=0$ (here we are using that $\phi$ is the Busemann quasicocycle for the action on $\mathcal C \ell$); moreover, $\psi(gTg^{-1})=0$ by \Cref{cor:bounded_orbit_implies_trivial}, since $gTg^{-1}$ fixes the bounded subset $\rho^{g\ell}_{\ell^\bot}\subset \mathcal C \ell^\bot$.
        \end{claimproof}

        We now turn to the proof of partial realisation. Let $\mathcal V=\{V_1,\ldots,V_k\}\subset \mathfrak S$ be an orthogonal collection. Up to reordering $\mathcal V$ suppose that $V_i=g_i\ell$ if and only if $i\le T$ for some $T\le k$. Fix $t\le T$; then for all $i\le t$ choose $p_i\in g_iL_\lambda$, and for all $i>t$ choose $p_i\in \mathcal C V_i$. We shall prove that, for every $t$, there exist a uniform constant $K_t$ and an element $g\in G$ $K_t$-coarsely realising the given coordinates, meaning that:
        \begin{itemize}
            \item For all $i\le t$, $\mathrm{d}_{g_iL_\lambda}(g,p_i)\le K_t$;
            \item For all $i> t$, $\mathrm{d}_{\mathcal C V_i}(g,p_i)\le K_t$;
            \item If $W\not \in G\cdot \ell$ is transverse to, or properly contains, some $V_i$, then $\mathrm{d}_{\mathcal C W}(g,\rho^{V_i}_W)\le K_t$;
            \item If $W=g\ell$ for some $g\in G$ and $W$ is transverse to, or properly contains, some $V_i$, then $\mathrm{d}_{gL_\lambda}(g,\rho^{V_i}_{g\ell_\lambda})\le K_t$.
        \end{itemize}
        Since since there is a uniform bound on the cardinality of orthogonal collections by \Cref{lem:pairwise_orth_are_at_most_E}, there are finitely many possible values of $t$, so setting $K=\max K_{t}$ will give a uniform constant not depending on $t$. This will then imply the partial realisation axiom for $(G,\mathfrak S_\lambda)$, which is the case $t=T$. 

        We shall proceed by induction on $t$, so we first assume $t=0$. By the partial realization axiom for $(Z,\mathfrak S)$, there exists $g\in G$ whose coordinates in $\mathfrak S$ $E$-coarsely realise the tuple $\{(V_i,p_i)\}$, so the only bullet point of the above list we have to check is the last one. Up to the $G$-action by translation, suppose some $V_i$ is transverse to $\ell$, and therefore also to $\ell^\bot$ by \Cref{notation:tweakable_hhg}.\eqref{need:orth_compl}. By definition of the realisation point in $\mathfrak S$, $\max\{\mathrm{d}_{\ell}(g,\rho^{V_i}_{\ell}),\mathrm{d}_{\ell^\bot}(g,\rho^{V_i}_{\ell^\bot})\}\le E$; in turn, by \Cref{claim:what_determines_pilambda}, there exists a uniform constant $K_0\ge E$ such that $\mathrm{d}_{L_\lambda}(g,\rho^{V_i}_{\ell_\lambda})\le K_0$, and we are done.


        Now suppose $t'>0$ and that the conclusion holds with $t'-1$ coordinates chosen from the new quasilines. Up to the $G$-action, suppose that $V_1=\ell$, and choose any $q\in \mathcal C \ell$. By induction, the tuple $\{(\ell,q)\}\cup\{(V_i,p_i)\}_{i=2,\ldots,k} $ is $K_{t-1}$-coarsely realised by some $g_0\in G$. By \Cref{claim:action_of_T} the $\langle T\rangle$-action on $L_\lambda$ is $C$-cobounded for some $C$, so we can find a power $m\in \mathbb{Z}$ such that $g\coloneq T^mg_0$ satisfies $\mathrm{d}_{L_\lambda}(g,p_1)\le C$. We now check that $g\in G$ $K_t$-coarsely realises $\{(V_i,p_i)\}_{i=1,\ldots, k}$, for some uniform constant $K_t\ge 0$.
         \begin{itemize}
            \item By construction $\mathrm{d}_{L_\lambda}(g,p_1)\le C$; moreover, since $\mathrm{d}_{L_\lambda}(g_0,p_i)\le K_{t-1}$ for all $2\le i\le t$, and since $\langle T\rangle$ acts with uniformly bounded orbits on $g_i \ell$ by \Cref{claim:action_of_T}, we see that $\mathrm{d}_{L_\lambda}(g,p_i)$ is uniformly bounded. 
            \item For the same reason as above, $\mathrm{d}_{\mathcal C V_i}(g,p_i)$ is uniformly bounded for all $i>t$.
            \item Suppose $W\not \in G\cdot \ell$ is transverse to, or properly contains, some $V_i$. Since $\langle t\rangle$ fixes every $V_i$ by \Cref{notation:tweakable_hhg}, $T^{-m}W$ is also transverse to, or properly contains, some $V_i$. Thus, by $G$-equivariance of the original (relative) projections, $\mathrm{d}_{\mathcal C W}(g,\rho^{V_i}_W)=\mathrm{d}_{\mathcal C (g^{-1}W)}(g_0,\rho^{V_i}_{g^{-1}W})\le K_{t-1}.$
            \item The same argument, but using that the new projections are $G$-equivariant, shows that, whenever $W=g\ell$ is transverse to, or properly contains, some $V_i$, then $\mathrm{d}_{gL_\lambda}(g,\rho^{V_i}_{g\ell_\lambda})\le K_{t-1}$.
        \end{itemize}



            \medskip\textbf{(Uniqueness.)} Let $r\ge 0$, and suppose $x,y\in Z$ satisfy $\mathrm{d}_{W}(x,y)\le r$ for all $W\in \mathfrak S-G\cdot \ell$ and $\mathrm{d}_{gL_\lambda}(x,y)\le r$ for all $g\in G$. If we prove that $\mathrm{d}_{\mathcal C (g \ell)}(x,y)$ is uniformly bounded (meaning, independently of $g$, $x$, and $y$), then the uniqueness axiom for the original structure will bound $\mathrm{d}_Z(x,y)$ in terms of $r$; furthermore, up to the $G$-action by translation, it is enough to show that $\mathrm{d}_{\mathcal C (\ell)}(x,y)$ is uniformly bounded (meaning, independently of $x$ and $y$). Let $x'=\mathfrak{g}_\ell(x)$ and $y'=\mathfrak{g}_\ell(y)$, which both lie in $P_\ell=\operatorname{Stab}_{G}(\ell)$; notice that, by how the gate is defined, $x'$ (resp. $y'$) projects $E$-close to $x$ (resp. $y$) both in $\mathcal C\ell$ and $\mathcal C\ell^\bot$. Since $\theta_\lambda\colon\operatorname{Stab}_{G}(\ell)\to L_\lambda$ is a quasi-isometry, and since $\pi_{L_\lambda(x)}$ (resp. $\pi_{L_\lambda(x)}$) is the image of $x'$ (resp. $y'$) in $L_\lambda(x)$, the difference 
        \[|\theta_\lambda(x')-\theta_\lambda(y')|=|(\phi(x')-\phi(y'))+\lambda(\psi(x')-\psi(y'))|\]
        is uniformly bounded. Furthermore, since $\psi\colon \operatorname{Stab}_{G}(\ell)\to \mathbb{R}$ is $\mathcal C\ell^\bot$-coarsely-Lipschitz, we also get that $|\psi(x')-\psi(y')|$ is uniformly bounded; hence $|\phi(x')-\phi(h')|$ is uniformly bounded by the triangular inequality. But then this means that $\mathrm{d}_{\mathcal C\ell}(x',y')$ is uniformly bounded, because in \Cref{construction:newline} we assumed that $\mathcal C\ell$ is the quasiline associated to $\phi$ and therefore $\phi\colon \mathcal C\ell\to \mathbb{R}$ is a quasi-isometry.


        \medskip\textbf{(Large links.)} We shall prove the passing up axiom \ref{axiom:passing_up}. Fix a constant $D$, greater than the original HHS constant $E$, such that, for any two points $x,y\in Z$, if $\mathrm{d}_{\mathcal C\ell}(x,y)\le E$ and $\mathrm{d}_{\mathcal C\ell^\bot}(x,y)\le 3E$, then $\mathrm{d}_{L_\lambda}(x,y)\le D$, which exists by \Cref{claim:what_determines_pilambda}. Now fix $t>0$, and let $P(t)$ be the integer appearing in the Passing up axiom for $(Z,\mathfrak S)$. We shall prove the passing up axiom with HHS constant at least $D$ and with at least $Q(t)=2P(t)-2+P(21E)$ domains. More precisely, we shall prove the contrapositive: given $V\in \mathfrak S$, $x,y\in Z$, and $\{U_i\}_{i=1}^Q\subseteq \mathfrak S_V$ satisfying $\mathrm{d}_{U_i}(x,y)>D$, we shall assume that no domain $W$ inside $V$ properly contains some $U_i$ and is such that $\mathrm{d}_W(x,y)>t$, and we shall prove that $Q\le Q(t)$. 

        By the original passing up axiom, at most $P(t)-1$ of the $U_i$ are not in the $G$-orbit of $\ell$, so all the other $U_i$ are of the form $g_i \ell$ for some $g_i\in G$. For each such $i$, either $\mathrm{d}_{\mathcal C(g_i\ell)}(x,y)> E$ or $\mathrm{d}_{\mathcal C(g_i\ell)^\bot}(x,y)> 3E$, by how we defined $D$. Again, the original passing up axiom implies that at most $P(t)-1$ of the $g_i \ell$ can satisfy $\mathrm{d}_{\mathcal C(g_i\ell)}(x,y)> E$, so there are at least $Q'=Q-2P(t)-2$ domains of the form $U_i=g_i\ell$ satisfying $\mathrm{d}_{\mathcal C(g_i\ell)^\bot}(x,y)> 3E$.

